insert into market.comparable_properties(
  property_id, provider, provider_listing_id, channel, listing_url, listing_name,
  location_name, property_type, bedrooms, bathrooms, accommodates, beds,
  rating, review_count, amenities, source_label, source_observed_at,
  data_quality, snapshot_notes, included, active
)
select
  '22222222-2222-4222-8222-222222222222'::uuid,
  provider, provider_listing_id, channel, listing_url, listing_name,
  location_name, property_type, bedrooms, bathrooms, accommodates, beds,
  rating, review_count, amenities, source_label, source_observed_at,
  data_quality, snapshot_notes, included, true
from seed
on conflict (property_id, provider, provider_listing_id) do update set
  channel = excluded.channel,
  listing_url = excluded.listing_url,
  listing_name = excluded.listing_name,
  location_name = excluded.location_name,
  property_type = excluded.property_type,
  bedrooms = excluded.bedrooms,
  bathrooms = excluded.bathrooms,
  accommodates = excluded.accommodates,
  beds = excluded.beds,
  rating = excluded.rating,
  review_count = excluded.review_count,
  amenities = excluded.amenities,
  source_label = excluded.source_label,
  source_observed_at = excluded.source_observed_at,
  data_quality = excluded.data_quality,
  snapshot_notes = excluded.snapshot_notes,
  included = excluded.included,
  active = true,
  updated_at = now();

insert into market.public_listing_snapshots(
  comparable_property_id, observed_at, public_metadata, content_sha256
)
select
  cp.id,
  cp.source_observed_at::timestamptz,
  jsonb_build_object(
    'provider', cp.provider,
    'providerListingId', cp.provider_listing_id,
    'channel', cp.channel,
    'listingUrl', cp.listing_url,
    'listingName', cp.listing_name,
    'locationName', cp.location_name,
    'propertyType', cp.property_type,
    'bedrooms', cp.bedrooms,
    'bathrooms', cp.bathrooms,
    'accommodates', cp.accommodates,
    'beds', cp.beds,
    'rating', cp.rating,
    'reviewCount', cp.review_count,
    'amenities', cp.amenities,
    'sourceLabel', cp.source_label,
    'dataQuality', cp.data_quality,
    'snapshotNotes', cp.snapshot_notes
  ),
  encode(digest(concat_ws('|', cp.provider, cp.provider_listing_id, cp.source_observed_at::text), 'sha256'), 'hex')
from market.comparable_properties cp
where cp.property_id = '22222222-2222-4222-8222-222222222222'::uuid
  and cp.source_observed_at = date '2026-07-28'
on conflict (comparable_property_id, observed_at) do nothing;

commit;
